//! Result screen: which side the player is on, and its numbers.
//!
//! The `CLEAR TYPE` caption of the score panel tells both "this is a result
//! screen" and the side (the 2P panel is the 1P one shifted right). Each
//! number is a right-aligned run of fixed-pitch digit cells read against a
//! font's digit masks. All coordinates, masks and thresholds come from
//! `resources/<w>x<h>/result.json`, generated by `tools/resgen` from our own
//! labelled screenshots.

use std::collections::BTreeMap;

use image::RgbImage;
use iu_core::Side;
use iu_core::label::ResultJudge;
use serde::{Deserialize, Serialize};

use crate::mask::{Ink, Mask};

pub const RESOURCE_VERSION: u32 = 1;

/// A cell with this many ink pixels or fewer is blank.
const BLANK_MAX_ONES: u32 = 2;

/// Size and spacing of one font's digit cells, with its 0–9 masks.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Font {
    pub width: u32,
    pub height: u32,
    pub pitch: u32,
    /// Masks for 0–9, in order.
    pub digits: Vec<Mask>,
    /// A cell further than this from every mask is not a digit.
    pub max_distance: u32,
}

/// The numbers read from the result screen.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum NumberField {
    Pg,
    Gr,
    Gd,
    Bd,
    Pr,
    ComboBreak,
    Fast,
    Slow,
    Score,
    BestScore,
    MissCount,
    BestMissCount,
    Notes,
}

impl NumberField {
    pub const ALL: [NumberField; 13] = [
        NumberField::Pg,
        NumberField::Gr,
        NumberField::Gd,
        NumberField::Bd,
        NumberField::Pr,
        NumberField::ComboBreak,
        NumberField::Fast,
        NumberField::Slow,
        NumberField::Score,
        NumberField::BestScore,
        NumberField::MissCount,
        NumberField::BestMissCount,
        NumberField::Notes,
    ];

    /// Fields that may show "—" instead of a number.
    pub fn nullable(self) -> bool {
        matches!(
            self,
            NumberField::MissCount | NumberField::BestMissCount | NumberField::BestScore
        )
    }
}

/// Where one number is drawn.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FieldPos {
    /// Top-left of the rightmost (ones) cell.
    pub x: u32,
    pub y: u32,
    /// Cells to the left of it, ones included.
    pub cells: u32,
    /// Key into [`ResultResources::fonts`].
    pub font: String,
    pub ink: Ink,
}

/// One side's caption anchor and number positions.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SideLayout {
    pub side: Side,
    /// Top-left of the `CLEAR TYPE` caption mask.
    pub caption: [u32; 2],
    pub fields: BTreeMap<String, FieldPos>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ResultResources {
    pub version: u32,
    pub width: u32,
    pub height: u32,
    pub caption: Mask,
    /// A frame is a result screen when the caption is within this distance.
    pub caption_max_distance: u32,
    pub sides: Vec<SideLayout>,
    pub fonts: BTreeMap<String, Font>,
}

/// Everything read from one result screen.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ResultReading {
    pub side: Side,
    pub judge: ResultJudge,
    pub combo_break: u32,
    pub fast: u32,
    pub slow: u32,
    pub score: u32,
    pub best_score: Option<u32>,
    pub miss_count: Option<u32>,
    pub best_miss_count: Option<u32>,
    pub notes: u32,
}

#[derive(Debug, thiserror::Error)]
pub enum ResourceError {
    #[error("result resources are not valid JSON: {0}")]
    Json(#[from] serde_json::Error),
    #[error("result resources are version {0}, this build reads {RESOURCE_VERSION}")]
    Version(u32),
    #[error("result resources are inconsistent: {0}")]
    Invalid(String),
}

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum ReadError {
    #[error("{field:?}: cell {cell} is not a digit (distance {distance})")]
    Unreadable {
        field: NumberField,
        cell: u32,
        distance: u32,
    },
    #[error("{0:?}: no number")]
    Empty(NumberField),
    #[error("{0:?}: not in the resources")]
    Missing(NumberField),
}

pub fn field_key(f: NumberField) -> String {
    serde_json::to_value(f)
        .ok()
        .and_then(|v| v.as_str().map(str::to_owned))
        .expect("unit variants serialize as strings")
}

impl ResultResources {
    pub fn from_json(json: &str) -> Result<Self, ResourceError> {
        let res: Self = serde_json::from_str(json)?;
        if res.version != RESOURCE_VERSION {
            return Err(ResourceError::Version(res.version));
        }
        for (name, font) in &res.fonts {
            if font.digits.len() != 10
                || font
                    .digits
                    .iter()
                    .any(|m| (m.width(), m.height()) != (font.width, font.height))
            {
                return Err(ResourceError::Invalid(format!("font {name}: bad masks")));
            }
        }
        for side in &res.sides {
            for (name, f) in &side.fields {
                if !res.fonts.contains_key(&f.font) {
                    return Err(ResourceError::Invalid(format!(
                        "field {name} uses unknown font {}",
                        f.font
                    )));
                }
            }
        }
        Ok(res)
    }

    /// The side whose score panel is on screen, if this is a result screen.
    pub fn detect(&self, img: &RgbImage) -> Option<&SideLayout> {
        if img.dimensions() != (self.width, self.height) {
            return None;
        }
        self.sides
            .iter()
            .map(|s| (self.caption.distance_at(img, s.caption[0], s.caption[1]), s))
            .filter(|(d, _)| *d <= self.caption_max_distance)
            .min_by_key(|(d, _)| *d)
            .map(|(_, s)| s)
    }

    pub fn read(&self, img: &RgbImage, side: &SideLayout) -> Result<ResultReading, ReadError> {
        let num = |f| self.read_field(img, side, f);
        let req = |f| num(f)?.ok_or(ReadError::Empty(f));
        Ok(ResultReading {
            side: side.side,
            judge: ResultJudge {
                pg: req(NumberField::Pg)?,
                gr: req(NumberField::Gr)?,
                gd: req(NumberField::Gd)?,
                bd: req(NumberField::Bd)?,
                pr: req(NumberField::Pr)?,
            },
            combo_break: req(NumberField::ComboBreak)?,
            fast: req(NumberField::Fast)?,
            slow: req(NumberField::Slow)?,
            score: req(NumberField::Score)?,
            best_score: num(NumberField::BestScore)?,
            miss_count: num(NumberField::MissCount)?,
            best_miss_count: num(NumberField::BestMissCount)?,
            notes: req(NumberField::Notes)?,
        })
    }

    /// One number: `Ok(None)` when the field shows "—" (only for nullable
    /// fields) or nothing.
    pub fn read_field(
        &self,
        img: &RgbImage,
        side: &SideLayout,
        field: NumberField,
    ) -> Result<Option<u32>, ReadError> {
        let pos = side
            .fields
            .get(&field_key(field))
            .ok_or(ReadError::Missing(field))?;
        let font = &self.fonts[&pos.font];
        let mut digits = Vec::new();
        for cell in 0..pos.cells {
            let Some(x) = pos.x.checked_sub(cell * font.pitch) else {
                break;
            };
            let m = Mask::from_image_ink(img, x, pos.y, font.width, font.height, pos.ink);
            if m.count_ones() <= BLANK_MAX_ONES {
                break; // right-aligned: the number ended
            }
            let (digit, distance) = classify(font, &m);
            if distance > font.max_distance {
                if field.nullable() && digits.is_empty() {
                    return Ok(None); // "—"
                }
                return Err(ReadError::Unreadable {
                    field,
                    cell,
                    distance,
                });
            }
            digits.push(digit);
        }
        if digits.is_empty() {
            return if field.nullable() {
                Ok(None)
            } else {
                Err(ReadError::Empty(field))
            };
        }
        Ok(Some(digits.iter().rev().fold(0, |acc, d| acc * 10 + d)))
    }
}

/// Nearest digit mask and its distance.
pub fn classify(font: &Font, cell: &Mask) -> (u32, u32) {
    font.digits
        .iter()
        .enumerate()
        .map(|(d, m)| (d as u32, m.distance(cell)))
        .min_by_key(|&(_, dist)| dist)
        .expect("10 digit masks")
}
